// A classic worker also supports MediaPipe's pinned Emscripten script loader.
let runtime=null,photo=null;let queue=Promise.resolve();
self.onmessage=({data:m})=>{queue=queue.then(async()=>{try{const progress=value=>self.postMessage({id:m.id,progress:value});if(!runtime){const {createSegmenter}=await import('./segment-runtime.js?v=20261025-hdr3');runtime=await createSegmenter(m.engine,progress,m.options||{});}if(m.type==='load'){self.postMessage({id:m.id,result:{ready:true}});return;}if(m.image){photo=m.photo;await runtime.setImage(m.image,progress);}if(photo!==m.photo)throw Error('The source photo changed. Tap again.');const result=await runtime.segment(m.points,m.box);self.postMessage({id:m.id,result},result.candidates.map(c=>c.mask.buffer));}catch(error){self.postMessage({id:m.id,error:error.message||String(error)});}});};
